/**
 * Test flow for addWorknoteLinkToContext action
 * Demonstrates adding a worknote link to the context
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testAddWorknoteLinkToContext = Flow(
    {
        $id: Now.ID['test_add_worknote_link_to_context_flow'],
        name: 'Test Add Worknote Link To Context',
        description: 'Tests the addWorknoteLinkToContext core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_add_worknote_link_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.addWorknoteLinkToContext,
            { $id: Now.ID['test_add_worknote_link_action'] },
            {
                table: 'incident',
                record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
                additional_comments: 'Test worknote added by flow',
                journal_field: 'work_notes',
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_add_worknote_link_log'] },
            {
                log_level: 'info',
                log_message: `addWorknoteLinkToContext outputs: type=${wfa.dataPill(result.type, 'string')}`,
            }
        )
    }
)
